import { describe, test, expect } from 'vitest';
import { ZimmSizeChipGroup } from './zimmSizeChipGroup.css';

/**
 * `index.test.tsx` mocks `useMultiStyleConfig` globally, so this recipe's own object shape is
 * never exercised by any shipped component test — these assertions are the only thing that
 * actually reads it. Guards against the exact regression the SFCC-236 Step 6 visual audit found:
 * `radiogroup` shipped with no `justifyContent`/`gap` at all, which rendered every chip flush
 * against its neighbour (confirmed live: 28px-wide chips exactly 28px apart, i.e. touching).
 */
describe('ZimmSizeChipGroup — recipe wiring', () => {
  test('every declared part is produced by baseStyle', () => {
    const parts = Object.keys(ZimmSizeChipGroup.baseStyle());
    expect(parts.sort()).toEqual([...ZimmSizeChipGroup.parts].sort());
  });

  test('radiogroup spreads chips with space-between, not a gap value — matches the real Figma SizeSelector (node 40002163:41459: flex items-center justify-between w-[208px])', () => {
    const { radiogroup } = ZimmSizeChipGroup.baseStyle();
    expect((radiogroup as Record<string, unknown>).justifyContent).toBe('space-between');
    expect(Object.prototype.hasOwnProperty.call(radiogroup, 'gap')).toBe(false);
  });
});

import type { SystemStyleObject } from '@chakra-ui/react';

/** State the atom feeds in so the recipe can resolve the Figma state cascade. */
type ZimmSizeChipStyleProps = {
  selected?: boolean;
  disabled?: boolean;
};

/**
 * Border colour precedence: disabled > selected > default — same "no state stacking" shape as
 * zimmTextInput.css.ts's resolveBorderColour. Default and Disabled both resolve to
 * 'transparent' rather than a real colour: Figma's Default/Disabled variants (nodes
 * 40003038:125875 / :125873) render as plain text with no box at all, so the always-present
 * `border` shorthand on `chip` below is made invisible rather than removed outright — the same
 * "transparent border avoids a layout shift" idiom zimmColourSwatch.css.ts's `swatch` part
 * uses for its own unselected state.
 */
export const resolveBorderColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent'; // Figma Disabled (…125873): no box, muted text only
  if (selected) return 'var(--zimm-color-border-focus)'; // Figma Selected (…125874): outline-only box
  return 'transparent'; // Figma Default (…125875): no box, plain text
};

/**
 * Background is transparent in every branch: Figma's Selected variant (…125874) is an
 * outline-only box — border present, no fill — so no state here ever paints a background.
 * Kept as an explicit disabled/selected/default cascade, matching the other two resolvers'
 * shape, rather than collapsed to a bare `'transparent'` return, so a future Figma revision
 * that does introduce a fill only has to change one branch's value.
 */
export const resolveBackgroundColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent';
  if (selected) return 'transparent'; // outline-only box — was var(--zimm-color-bg-05); Figma has no fill
  return 'transparent';
};

/**
 * Text colour precedence: disabled > selected > default. Selected does NOT get an inverted
 * (white) treatment — Figma's Selected variant (…125874) keeps the same dark default text
 * colour as Default and only adds the outline box via resolveBorderColour above.
 */
export const resolveTextColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'var(--zimm-color-text-muted)';
  if (selected) return 'var(--zimm-color-text-default)'; // no inversion — outline-only box, not filled
  return 'var(--zimm-color-text-default)';
};

/**
 * Recipe for the PDP size chip atom — a single 28x28 (--zimm-scale-700) size option, read
 * directly off the size-chip Figma component set (node 40003038:125876) for this exact
 * component's dimensions and state list. Four Figma-defined states — Default / Selected /
 * Focus / Disabled — resolved by the three `resolveXxxColour` helpers above and the
 * `_focusVisible` block below. Hover and Active/pressed are NOT part of that variant set, so
 * neither is implemented here — same "don't invent an unspecified visual state" precedent as
 * zimmColourSwatchGroup.css.ts's `pageButton` part.
 *
 * The STRUCTURE of all four states is directly confirmed against individual Figma PNG exports
 * of each variant (Default …125875, Selected …125874, Disabled …125873, Focus …130506) — not
 * inferred: Default and Disabled render as plain text with no border/box at all; Selected is
 * an outline-only box (border present, no fill — text stays the normal default colour rather
 * than inverting); Focus is Selected's border box plus an additional outer ring (confirmed by
 * its 34x34 Figma frame vs. 28x28 for the other three — the ring extends past the chip
 * itself). Only the exact border/text COLOUR TOKEN choice (`--zimm-color-border-focus` /
 * `--zimm-color-text-default` / `--zimm-color-text-muted`) remains this file's own inference
 * from precedent rather than a pixel-confirmed hex breakdown — flag for UI-designer
 * confirmation if a token choice doesn't match.
 */
export const ZimmSizeChip = {
  parts: ['chip'],
  baseStyle: (props: ZimmSizeChipStyleProps): Record<string, SystemStyleObject> => ({
    chip: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-700)', // 28px
      height: 'var(--zimm-scale-700)', // 28px
      // Width/style stay constant across every state; only borderColor toggles between
      // 'transparent' (Default/Disabled — no visible box) and a real token (Selected) — see
      // resolveBorderColour above.
      border: 'var(--zimm-border-width-default) solid',
      borderColor: resolveBorderColour(props),
      background: resolveBackgroundColour(props),
      color: resolveTextColour(props),
      textStyle: 'buttonSm',
      padding: 0,
      outline: 'none',
      cursor: props.disabled ? 'not-allowed' : 'pointer',
      _focusVisible: {
        // Figma's Focus variant (…130506) shows a border box even when the chip isn't
        // selected, so focus-visible applies the same border colour Selected uses, on top of
        // (not instead of) the outer ring — an unselected-but-tabbed-to chip still gets a
        // visible box, not just a ring around otherwise-invisible bounds.
        borderColor: 'var(--zimm-color-border-focus)',
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  }),
};

// Source: Zimmermann Design System 2026 (Handover tokens/colors.css).
// Brand primitive and semantic alias colour tokens. The alias tier below
// references the primitive tier via plain object lookups (`grey[900]`)
// rather than retyping each hex value a second time.

const grey = {
  black: 'black',
  900: '#191919',
  800: '#282828',
  700: '#454545',
  600: '#666666',
  500: '#707070',
  300: '#969696',
  200: '#d1d1d1',
  100: '#e6e6e6',
  white: '#ffffff',
};

const ivory = {
  400: '#f2e9e0',
  300: '#fbf5ef',
  200: '#f6f4f1',
  100: '#f9f8f6',
};

const coral = { 500: '#f98f8c' };
const green = { 500: '#2d5a3d' };
const orange = { 500: '#d67600' };
const red = { 500: '#9c0000' };

// Opacity (base: grey/900 #191919)
const opacity = {
  50: 'rgba(25, 25, 25, 0.50)',
  40: 'rgba(25, 25, 25, 0.40)',
  30: 'rgba(25, 25, 25, 0.30)',
  15: 'rgba(25, 25, 25, 0.15)',
};

export const colors = {
  // ---- Brand / Primitive ----
  grey,
  ivory,
  coral,
  green,
  orange,
  red,
  opacity,

  // ---- Alias / Semantic: Background ----
  background: {
    '01': ivory[100],
    '02': ivory[200],
    '03': ivory[300],
    '04': ivory[400],
    '05': grey[900],
    '06': grey[800],
    '07': grey.white,
  },
  // ---- Alias / Semantic: Text ----
  text: {
    default: grey[900],
    inverse: grey.white,
    // Handover contradicts itself here: tokens/colors.css says #969696 "confirmed",
    // but tokens.md and contract/zimm-contract.js say #939393 and still flag it
    // unresolved. Shipping the colors.css value (grey[300]); confirm with the UI designer.
    inverseGrey: grey[300],
    secondary: grey[600],
    muted: grey[300],
  },
  // ---- Alias / Semantic: Border ----
  border: {
    default: grey[100],
    secondary: grey[200],
    focus: grey[900],
    forms: grey[500],
    error: red[500], // no Handover counterpart; retained for form validation use
  },
  // ---- Alias / Semantic: Status ----
  status: {
    success: green[500],
    error: red[500],
    errorBackground: coral[500],
    storeClosed: orange[500],
  },
  // ---- Alias / Semantic: Link ----
  link: {
    default: grey[900],
    hover: grey[500],
  },
  // ---- Alias / Semantic: Icon ----
  icon: {
    default: grey[900],
    disabled: grey[200],
  },
  // ---- Alias / Semantic: Action: Primary ----
  action: {
    primary: {
      bgDefault: grey[900],
      bgHover: grey[300],
      bgPressed: grey[700],
      bgDisabled: grey[200],
      bgFocused: grey.black,
      text: grey.white,
      textDisabled: grey[300],
    },
    secondary: {
      border: grey[900],
      bgHover: ivory[100],
      text: grey[900],
      textInverse: grey.white,
      textDisabled: grey[300],
    },
  },
};

import { FONT_MEDIUM, FONT_REGULAR, FONT_SERIF } from './fonts';

// Typography scale primitives — deduplicated from the 22 Handover text styles below.
// zimmTokens.ts's --zimm-font-size-*/lineheight-*/letterspacing-* entries read from
// here too. Naming matches those --zimm-* suffixes.
export const fontSizes = {
  md: '1.5rem', // 24px
  xs: '1rem', // 16px
  '2xs': '0.875rem', // 14px
  '3xs': '0.75rem', // 12px
  '4xs': '0.625rem', // 10px
} as const;

export const lineHeights = {
  md: '2rem', // 32px
  xs: '1.5rem', // 24px
  '2xs': '1.125rem', // 18px
  '3xs': '1rem', // 16px
  '4xs': '0.875rem', // 14px
} as const;

export const letterSpacings = {
  sm: '0',
  xs: '-0.0075rem', // -0.12px
  // Only used by linkLg — still a named token rather than a raw literal so it can't
  // drift out of sync with globalStyles.ts's zimmTextLinkLg.
  '2xs': '-0.00875rem', // -0.14px
  footer: '0.025rem', // 0.4px
} as const;

export const fontWeights = {
  medium: '500',
  regular: '400',
} as const;

// Named text styles — source: Zimmermann Design System 2026 (Handover tokens/typography.css)
// Token name → fontFamily / fontWeight / fontSize / lineHeight / letterSpacing / transform
export const textStyles = {
  // ---- Headings ----
  // ZIM/h1-strong (.zimm-text-h1-strong): 500 weight, uppercase
  heading1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h1 (.zimm-text-h1): 400 weight, uppercase
  heading1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h2-strong (.zimm-text-h2-strong)
  heading2: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/h3-strong (.zimm-text-h3-strong)
  heading3: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'uppercase' as const,
  },
  // ---- Body ----
  // ZIM/body1-strong (.zimm-text-body1-strong)
  body1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body1 (.zimm-text-body1)
  body1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2-strong (.zimm-text-body2-strong)
  body2Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2 (.zimm-text-body2)
  body2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Mobile body ----
  // ZIM/Mobile/Body1-strong (.zimm-text-mobile-body1-strong)
  mobileBody1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/Mobile/Body1 (.zimm-text-mobile-body1)
  mobileBody1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/Mobile/Body2 (.zimm-text-mobile-body2)
  mobileBody2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Utility ----
  // ZIM/Label (.zimm-text-label)
  label: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // Default/Caption (.zimm-text-caption)
  caption: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Links ----
  // ZIM/Link-lg (.zimm-text-link-lg): uppercase + underline
  linkLg: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings['2xs'],
    textTransform: 'uppercase' as const,
    textDecoration: 'underline',
  },
  // ZIM/Link-sm (.zimm-text-link-sm): uppercase + underline. Corrected from 'capitalize' to
  // 'uppercase' 2026-09-03 — confirmed against the live rendered text on Figma node
  // 40002163:41468 ("NOTIFY ME", fully capitalised), not the Handover token name alone.
  linkSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'uppercase' as const,
    textDecoration: 'underline',
  },
  // ---- Buttons ----
  // ZIM/Button-lg — no .zimm-text-btn-lg class; zimmButton.css.ts composes this textStyle
  // directly (single source of truth for button styling).
  button: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/Button-sm — no .zimm-text-btn-sm class, same reason as the button style above.
  buttonSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ---- Commerce ----
  // ZIM/Product-name (.zimm-text-product-name)
  productNames: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/Price (.zimm-text-price)
  price: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Navigation ----
  // ZIM/Navigation (.zimm-text-nav)
  navigation: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: 'normal',
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ---- Footer ----
  // ZIM/Footer (.zimm-text-footer)
  footer: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['4xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.footer,
    textTransform: 'uppercase' as const,
  },
  // ---- Serif accent (Source Serif 4, italic) ----
  // Default/Serif (.zimm-text-serif)
  serif: {
    fontFamily: FONT_SERIF,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.regular,
    fontStyle: 'italic' as const,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
  },
};

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the touch-only PDP/card image position indicator — a 1px hairline strip, one
 * segment per image, the current position picked out by colour. Figma node 40002536:7957
 * ("Slide indicator"). Geometry AND colour are now both confirmed directly against the real
 * component (via `get_design_context` on three separate variants — 40002536:7956 (Qty=8,
 * selected=1), 40002536:7947 (Qty=5, selected=1), 40002536:7954 (Qty=5, selected=2) — chosen to
 * rule out any positional/count-dependent difference, and there is none): no inter-segment gap
 * (`flex items-center`, no gap class), equal-width segments (`flex-[1_0_0]`, an exact match for
 * this file's own `flex: '1 0 0'` below), and the active segment always painted with Figma's
 * `border/focus` token, every other segment with `border/secondary` — regardless of which index
 * is selected. `--zimm-scale-025` (1px height) was already correct from Step 1.
 *
 * Two parts:
 *   - `root` — the full-width flex strip, exactly `--zimm-scale-025` (1px) tall.
 *   - `dot` — one equal-width segment per image (despite the part name, this renders as a
 *     rectangle in a hairline, not a circular dot — the name matches this component's
 *     already-agreed contract, not a literal shape description).
 */
export const ZimmSlideIndicator = {
  parts: ['root', 'dot'],

  baseStyle: ({ isActive }: { isActive?: boolean }): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      // Fluid, not a fixed Figma px width — matches the product card's own "fluid, not 288px"
      // rule: this strip always spans whatever width its image parent gives it, rather than
      // the specific 159.11px/99.44px bounding boxes the two sampled Figma variants happened
      // to measure at their own artboard widths.
      width: '100%',
      height: 'var(--zimm-scale-025)', // 1px, confirmed correct since Step 1.
      // Confirmed no gap: Figma's own `flex items-center` has no gap class — segments are
      // genuinely flush-adjacent, not merely left at a default pending confirmation.
      gap: 0,
    },

    dot: {
      // Confirmed exact match: Figma's own `flex-[1_0_0]` on every segment, regardless of count
      // or which one is active.
      flex: '1 0 0',
      height: '100%',
      // Both previously read from the wrong semantic alias — `--zimm-color-bg-05` and
      // `--zimm-color-opacity-40` happened to LOOK plausible (the active one even resolves to
      // the identical hex, since bg-05 and border-focus both trace to the same grey/900
      // primitive) but were never actually confirmed against the design, per this file's own
      // prior comment. Confirmed via `get_design_context`: the active segment's colour matches
      // Figma's `border/focus` token; every other segment matches `border/secondary` — a flat,
      // opaque light grey, notably lighter than the semi-transparent overlay `opacity-40`
      // previously produced. The active branch below reads `--zimm-color-bg-05`, not
      // `--zimm-color-border-focus` — a `border.*` alias is the wrong token *category* for a
      // `background` CSS property even though both resolve to the identical grey/900 hex (see
      // `foundation/colour.ts`); `border.secondary` has no `background.*` counterpart to swap
      // to, so the inactive branch keeps referencing it directly. Both remain
      // already-registered tokens, not new ones.
      background: isActive ? 'var(--zimm-color-bg-05)' : 'var(--zimm-color-border-secondary)',
    },
  }),
