describe('ZimmSizeChipGroup — recipe wiring', () => {
  test('every declared part is produced by baseStyle', () => {
    const parts = Object.keys(ZimmSizeChipGroup.baseStyle());
    expect(parts.sort()).toEqual([...ZimmSizeChipGroup.parts].sort());
