  test('radiogroup spreads chips with space-between, not a gap value — matches the real Figma SizeSelector (node 40002163:41459: flex items-center justify-between w-[208px])', () => {
    const { radiogroup } = ZimmSizeChipGroup.baseStyle();
    expect((radiogroup as Record<string, unknown>).justifyContent).toBe('space-between');
    expect(Object.prototype.hasOwnProperty.call(radiogroup, 'gap')).toBe(false);
  });
});

